SELECT coalesce(((f.k5 / f.k9) || (f.m2 + f.k6)), CAST((f.m1 + f.k4) AS DECIMAL(18, 2))) AS e0, sum(f.m11) OVER (PARTITION BY f.k12 ORDER BY f.ts0 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS w1, sum(CASE WHEN NOT (f.k14 IN (8587, 9687, 8836, 9803, 7511, 1105, 364, 5336, 8512, 3188)) THEN f.m15 ELSE 0 END) AS a2, (99836 + f.k1) AS e3, CASE WHEN sum(f.m4) FILTER (WHERE (f.k5 IN (701, 908, 2442, 4237, 8448, 7961) OR f.k12 IN (2164, 1819, 1841, 1638, 4375, 88, 8555, 7218, 2731, 1155, 3983))) > 5653 THEN 'h' ELSE 'l' END AS s4, f.k13 AS c5, sum(f.m9) AS a6, f.k8 AS c7, f.k7 AS c8, sum(f.m3) FILTER (WHERE (f.k9 IS NOT NULL AND f.k0 BETWEEN 31 AND 8933)) AS a9, f.k9 AS c10, row_number() OVER (PARTITION BY f.k8 ORDER BY f.k3 DESC) AS w11, f.k7 AS c12, CASE WHEN sum(f.m15) > 3872 THEN 'h' ELSE 'l' END AS s13, f.k9 AS c14, (CAST(CASE WHEN NOT (f.k7 BETWEEN 184 AND 2948) THEN f.m9 ELSE 88103 END AS DECIMAL(18, 2)) * CASE WHEN NOT (f.k9 IN (2366, 575, 6073)) THEN (f.k14 / f.k1) ELSE coalesce(f.k10, 70033) END) AS e15, f.k13 AS c16, f.k10 AS c17, CAST((f.k15 + 15081) AS DECIMAL(18, 2)) AS e18, count(*) AS a19, f.k1 AS c20, sum(f.m14) OVER (PARTITION BY f.k1 ORDER BY f.ts0 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS w21, (CAST(CAST(f.m14 AS DECIMAL(18, 2)) AS DECIMAL(18, 2)) / CASE WHEN (f.s2 LIKE 'p%' OR f.s5 LIKE 'p%') THEN CAST(f.k3 AS DECIMAL(18, 2)) ELSE coalesce(16473, f.k14) END) AS e22, CASE WHEN sum(f.m12) FILTER (WHERE NOT (f.k15 IN (3686, 7772, 4555, 2298, 3889, 9237, 1486, 5985, 8223))) > 554 THEN 'h' ELSE 'l' END AS s23, round(coalesce(CAST(f.m8 AS DECIMAL(18, 2)), round(f.k10, 2)), 2) AS e24, ((CAST(f.k6 AS DECIMAL(18, 2)) || (f.m12 / f.m1)) - CASE WHEN (f.s0 LIKE 'p%' OR f.k2 IS NOT NULL) THEN (56916 + 38633) ELSE coalesce(f.k7, f.k15) END) AS e25, CASE WHEN sum(f.m11) > 2353 THEN 'h' ELSE 'l' END AS s26, f.k1 AS c27, sum(f.m7) AS a28, sum(f.m11) FILTER (WHERE (f.k12 > 26057 AND f.k10 > 10478)) AS a29, f.k15 AS c30, CASE WHEN sum(CASE WHEN (f.k8 > 3399 AND f.k12 > 81572) THEN f.m9 ELSE 0 END) > 6717 THEN 'h' ELSE 'l' END AS s31, sum(f.m3) FILTER (WHERE (f.k1 IS NOT NULL AND f.k13 BETWEEN 21 AND 4847)) AS a32, rank() OVER (ORDER BY f.m3 DESC) AS w33, sum(f.m2) FILTER (WHERE (f.s6 LIKE 'p%' OR f.k15 IN (9425, 4976, 1809, 7020))) AS a34, sum(f.m6) OVER (PARTITION BY f.k10 ORDER BY f.ts0 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS w35, sum(CASE WHEN NOT (f.s7 LIKE 'p%') THEN f.m6 ELSE 0 END) AS a36, rank() OVER (ORDER BY f.m5 DESC) AS w37, coalesce(37537, 25497) AS e38, avg(f.m14) AS a39, f.k7 AS c40, f.k15 AS c41, sum(CASE WHEN NOT (f.k6 BETWEEN 404 AND 7231) THEN f.m14 ELSE 0 END) AS a42, sum(f.m7) AS a43, round(round((f.k2 + f.m2), 2), 2) AS e44, CASE WHEN sum(f.m6) FILTER (WHERE NOT (f.s3 LIKE 'p%')) > 2100 THEN 'h' ELSE 'l' END AS s45, count(*) AS a46, f.k14 AS c47, f.k12 AS c48, sum(f.m3) OVER (PARTITION BY f.k1 ORDER BY f.ts0 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS w49, CASE WHEN NOT (f.k10 IN (5918, 5398, 3185, 4490, 3587, 7126, 5224, 5278, 728)) THEN f.m15 ELSE f.k5 END AS e50, f.k1 AS c51, f.k5 AS c52, f.k5 AS c53, row_number() OVER (PARTITION BY f.k11 ORDER BY f.k3 DESC) AS w54, count(*) AS a55, count(DISTINCT f.s4) AS a56, (round(f.m14, 2) - (f.k14 || f.m0)) AS e57, ((6372 || f.k4) / (f.k12 || f.k1)) AS e58, f.k13 AS c59 FROM fact_f0 f INNER JOIN dim_d0 d0 ON f.k14 = d0.k14 INNER JOIN dim_d1 d1 ON f.k14 = d1.k14 LEFT JOIN dim_d2 d2 ON f.k3 = d2.k3 INNER JOIN dim_d3 d3 ON f.k13 = d3.k13 JOIN (SELECT k0, sum(m0) AS sub_m0, count(*) AS sub_c0 FROM fact_f1 WHERE ts0 >= DATE '2024-01-01' GROUP BY k0) sub0 ON sub0.k0 = f.k0 WHERE f.ts0 BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND f.k2 IN (2702, 7802, 1776, 5230, 2287, 6002, 9415, 4085, 7555, 1788, 2294, 7263, 1230, 2317, 3694, 8468, 1346, 758, 6692, 9302, 4466, 1805, 4586, 8266, 2635, 8765, 9874, 9489, 5961, 1073, 2685, 8478, 1350, 4349, 1641, 5129, 3064, 8696, 4338, 1035) AND f.k3 NOT IN (5964, 3200, 6490, 1448, 81, 7082, 6205, 6388, 7655, 8809) AND f.m0 > 0 GROUP BY f.k4, f.k10, f.k14, f.k12, f.k2, f.k13 HAVING count(*) > 1 AND sum(f.m0) > 0 ORDER BY a0 DESC NULLS LAST, c1 ASC, e2 DESC LIMIT 1000
